-- Membuat tabel feature_model_limit
CREATE TABLE IF NOT EXISTS feature_model_limit (
    fuID VARCHAR(50) PRIMARY KEY,
    label VARCHAR(255) NOT NULL,
    status VARCHAR(50) NOT NULL,
    releasibility_type VARCHAR(50) NOT NULL,
    limit_object_type VARCHAR(100) NOT NULL,
    arc_geometry_type VARCHAR(50) NOT NULL,
    start_life_span DATE NOT NULL,
    end_life_span DATE,
    horizontal_datum VARCHAR(50) NOT NULL
);

